class Animal {
    String name;
    Animal(String name) { this.name = name; }
    String speak() { return name + " makes a sound"; }
}
class Dog extends Animal {
    Dog(String name) { super(name); }
    @Override
    String speak() { return name + " barks"; }
}
class Solution {
    static String describe(String kind, String name) {
        Animal a = kind.equals("dog") ? new Dog(name) : new Animal(name);
        return a.speak();
    }
}

